CREATE TABLE "payments" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "payments_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"user_id" integer NOT NULL,
	"provider_id" text NOT NULL,
	"subscription_provider_id" text NOT NULL,
	"amount_cents" integer NOT NULL,
	"status" text NOT NULL,
	"status_detail" text,
	"charged_on" text NOT NULL,
	"created_at" text DEFAULT (to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) NOT NULL,
	"updated_at" text DEFAULT (to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) NOT NULL,
	CONSTRAINT "payments_status" CHECK ("status" IN ('approved', 'pending', 'rejected', 'refunded', 'cancelled')),
	CONSTRAINT "payments_charged_on" CHECK ("charged_on" ~ '^[0-9]{4}-[0-1][0-9]-[0-3][0-9]$'),
	CONSTRAINT "payments_amount" CHECK ("payments"."amount_cents" >= 0)
);
