CREATE TABLE "subscriptions" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "subscriptions_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"user_id" integer NOT NULL,
	"provider_id" text,
	"status" text DEFAULT 'pending' NOT NULL,
	"checkout_url" text,
	"price_cents" integer NOT NULL,
	"paid_until" text,
	"next_payment_date" text,
	"last_failure_at" text,
	"cancelled_at" text,
	"last_synced_at" text,
	"created_at" text DEFAULT (to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) NOT NULL,
	"updated_at" text DEFAULT (to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) NOT NULL,
	CONSTRAINT "subscriptions_status" CHECK ("status" IN ('pending', 'authorized', 'paused', 'cancelled')),
	CONSTRAINT "subscriptions_paid_until" CHECK ("paid_until" IS NULL OR "paid_until" ~ '^[0-9]{4}-[0-1][0-9]-[0-3][0-9]$'),
	CONSTRAINT "subscriptions_price" CHECK ("subscriptions"."price_cents" > 0)
);
